"""Replace invented Stitch Framer visuals with the observed public page media.

framer-stitch.html remains the unchanged native Stitch export. The generated
framer.html is a source-backed draft for later visual/responsive review.
"""

import html
import json
import re
from pathlib import Path
from string import Template


ROOT = Path(__file__).resolve().parent
raw = (ROOT / "framer-stitch.html").read_text()
for phrase in ("Framer is the design agent for", "Lighthouse 100/100", "All systems normal"):
    assert phrase in raw, f"Unexpected native Stitch source: {phrase}"
ref = json.loads((ROOT / "framer-browser-reference.json").read_text())
manifest = json.loads((ROOT / "framer-asset-provenance.json").read_text())
assert ref["hero"]["heading"] == "Framer is the design agent for every step from idea to launch"
for name in manifest:
    assert (ROOT / "framer-assets" / name).is_file(), name


def esc(value):
    return html.escape(value, quote=True)


def asset(filename):
    assert filename in manifest, filename
    return f"framer-assets/{filename}"


mark = re.search(r'(<svg class="w-4 h-6[^>]+>.*?</svg>)', raw, re.S)
assert mark, "Native Stitch Framer mark missing"
mark = mark.group(1)

explorations = [
    ("Exploration", "exploration-haus.jpg"),
    ("Exploration — Big Intro", "exploration-big-intro.jpg"),
    ("Exploration — Side Nav", "exploration-side-nav.jpg"),
]
exploration_html = "".join(
    f'<div class="exploration"><span>{esc(label)}</span><img src="{asset(filename)}" alt="{esc(label)} website preview" loading="lazy"></div>'
    for label, filename in explorations
)
wheel_html = "".join(
    f'<img src="{asset("code-wheel-" + str(n) + ".jpg")}" alt="Framer code component visual" loading="lazy">'
    for n in range(1, 5)
)
showcase_html = "".join(
    f'<img src="{asset(filename)}" alt="{esc(label)} built with Framer" loading="lazy">'
    for label, filename in [
        ("Featured site", "showcase-main.png"),
        ("Maggie site", "showcase-maggie.png"),
        ("Midlife Engineering site", "showcase-midlife.png"),
    ]
)
customers = "".join(f"<span>{esc(name)}</span>" for name in ref["customerNames"])

