    ("Product", [("AI", "https://www.framer.com/ai/"), ("Agents", "https://www.framer.com/agents/"), ("External Agents", "https://www.framer.com/agents/external/"), ("Design", "https://www.framer.com/design/"), ("Collaborate", "https://www.framer.com/collaborate/"), ("CMS", "https://www.framer.com/cms/"), ("Hosting", "https://www.framer.com/hosting/"), ("Performance", "https://www.framer.com/performance/"), ("SEO", "https://www.framer.com/seo/"), ("Skills", "https://www.framer.com/skills"), ("Convert", "https://www.framer.com/convert/"), ("Publish", "https://www.framer.com/publish/"), ("Updates", "https://www.framer.com/updates")]),
